{
  "identity": {
    "name": "Boise Remodeling Co.",
    "location": "Meridian, Idaho",
    "claims": [
      {
        "statement": "Boise Remodeling Co is an operating trade name and registered DBA of P5 Home Co LLC.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/",
        "quote": "Boise Remodeling Co is a DBA of P5 Home Co LLC"
      },
      {
        "statement": "The business operates from Meridian, Idaho with [redacted] listed as public representative.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/contact",
        "quote": "Public representative: [redacted] · 4031 W Wapoot St, Meridian, ID 83646 · Service-area business, not a staffed storefront"
      },
      {
        "statement": "The company operates as a service-area design-build remodeling contractor covering Ada and Canyon County.",
        "label": "inference",
        "sourceUrl": "https://boiseremodeling.co/contact",
        "quote": null
      }
    ]
  },
  "industry": {
    "industry": "Residential Design-Build Remodeling",
    "activities": [
      "Kitchen remodeling",
      "Bathroom remodeling",
      "Whole-home remodeling",
      "Room additions",
      "ADU / guest house construction",
      "Basement remodeling",
      "Outdoor living & decks",
      "Aging-in-place remodeling"
    ],
    "claims": [
      {
        "statement": "Boise Remodeling Co provides design-build residential remodeling services across Ada and Canyon County.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/",
        "quote": "Boise Remodeling Co is a design-build team for kitchens, bathrooms, additions, and whole-home work across Ada and Canyon County."
      },
      {
        "statement": "The company functions as the remodeling division of the P5 family of companies.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/about",
        "quote": "Boise Remodeling Co is the remodeling specialist in the P5 family."
      },
      {
        "statement": "The business is a general residential remodeling contractor rather than an HVAC, plumbing, or electrical trade contractor.",
        "label": "inference",
        "sourceUrl": "https://boiseremodeling.co/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://boiseremodeling.co/",
    "claims": [
      {
        "statement": "Boise Remodeling Co is part of the P5 Home Co brand group alongside construction, handyman, and cabinet entities.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/",
        "quote": "Part of P5 Home Co: Boise Construction Co · Boise Remodeling Co · Boise Handyman Co · Boise Cabinet Co · Boise ADU Co"
      },
      {
        "statement": "The company employs digital tracking tools to evaluate web traffic.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/privacy-policy",
        "quote": "We use Google Analytics 4 (GA4) to understand how visitors use this site"
      },
      {
        "statement": "The company actively runs paid advertising campaigns on Google, Facebook, and Instagram to acquire residential remodeling leads.",
        "label": "inference",
        "sourceUrl": "https://boiseremodeling.co/privacy-policy",
        "quote": null
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "Boise Remodeling Co operates under Idaho Registered Contractor license #8381215 held by P5 Home Co LLC.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/",
        "quote": "Idaho Registered Contractor #8381215 Boise Remodeling Co is a DBA of P5 Home Co LLC"
      },
      {
        "statement": "The company pulls building permits in-house for remodeling projects.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/",
        "quote": "All permits pulled in-house"
      }
    ],
    "limitations": "Contractor registration #8381215 is stated directly on the website under P5 Home Co LLC, but registration status, bond verification, and insurance coverage were not independently verified through the Idaho Division of Occupational and Professional Licenses."
  },
  "existingSoftware": [
    {
      "product": "Google Ads & Google Analytics 4",
      "purpose": "Web traffic measurement, ad conversion tracking, and call/text click attribution.",
      "evidence": {
        "statement": "The company uses Google Ads conversion tracking to measure quote requests, phone calls, and texts generated by advertising.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/privacy-policy",
        "quote": "Google Ads to measure which of our ads lead to quote requests, calls and texts."
      }
    },
    {
      "product": "Meta Pixel & Conversions API",
      "purpose": "Advertising measurement and lead attribution for Facebook and Instagram campaigns.",
      "evidence": {
        "statement": "The company tracks inquiries and lead conversion events via Meta Pixel and Conversions API.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/privacy-policy",
        "quote": "We also use the Meta Pixel and Meta's Conversions API to measure visits and inquiries"
      }
    },
    {
      "product": "Microsoft Clarity",
      "purpose": "Website user behavior recording and heatmap analysis.",
      "evidence": {
        "statement": "The site deploys Microsoft Clarity with masked form inputs to record user behavior.",
        "label": "fact",
        "sourceUrl": "https://boiseremodeling.co/privacy-policy",
        "quote": "We also use Microsoft Clarity to see how visitors use our pages through heatmaps and session recordings;"
      }
    },
    {
      "product": "Custom Next.js Web App & Subcontractor Portal",
      "purpose": "Lead generation, interactive remodel cost estimator, and subcontractor access.",
      "evidence": {
        "statement": "The site runs on Next.js with custom interactive estimating tools and an authenticated subcontractor portal link.",
        "label": "inference",
        "sourceUrl": "https://boiseremodeling.co/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The company specifies a response timeframe of within one business day for web form inquiries.",
      "label": "fact",
      "sourceUrl": "https://boiseremodeling.co/",
      "quote": "Tell us what to fix or renovate. We follow up within one business day."
    },
    {
      "statement": "Prospective clients who submit online requests experience up to a 24-hour business-day wait before receiving follow-up contact.",
      "label": "inference",
      "sourceUrl": "https://boiseremodeling.co/",
      "quote": null
    },
    {
      "statement": "Online inquiries submitted outside business hours or on weekends may experience delays in booking in-home consultations.",
      "label": "hypothesis",
      "sourceUrl": null,
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Web inquiry response times are up to one business day, allowing warm homeowner leads to shop competing remodelers.",
      "label": "inference",
      "basis": "The website explicitly sets client expectations to follow up within one business day for online consultation requests."
    },
    {
      "problem": "Manual coordination across paid lead sources (Google and Meta) and trade subcontractors may cause administrative overhead.",
      "label": "hypothesis",
      "basis": "The company runs multi-channel paid acquisition and uses independent subcontractors, but displays no automated field-service dispatch integration."
    },
    {
      "problem": "The business operates outside ForgeX's target segment of HVAC, plumbing, and electrical trade contractors.",
      "label": "fact",
      "basis": "The company is a residential design-build remodeling contractor specializing in kitchens, bathrooms, additions, and whole-home remodels."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Construction and Remodeling Management Software (e.g., Buildertrend, CoConstruct, or Jobber)",
      "addresses": "Lead pipeline intake, subcontractor scheduling, change order management, and client portal communications.",
      "alreadyOwned": false
    },
    {
      "solution": "Automated SMS / Calendar Booking integration (e.g., Twilio or Calendly embed)",
      "addresses": "Instant automated acknowledgment of web submissions and self-service in-home visit scheduling.",
      "alreadyOwned": false
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solutions are recommended because Boise Remodeling Co is outside ForgeX's defined target industry."
  },
