    "rating": "not applicable",
    "explanation": "Custom AI agent delivery is not applicable as no service offering is proposed."
  },
  "humanReview": [
    "General contractor review of project scopes, architectural plans, and municipal permit applications.",
    "Manual approval of subcontractor contracts, milestone draws, and written change orders."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Engaging home remodeling and design-build firms introduces extended sales cycles and complex custom construction scopes that do not align with ForgeX's standardized MEP contractor workflows."
    },
    {
      "type": "compliance",
      "description": "Automated consumer outreach or text messaging must comply with TCPA rules and state contractor licensing regulations."
    }
